// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 amount, address actor) public {
        vm.assume(recipient != address(0));
        vm.assume(actor != address(this));
        vm.assume(recipient != actor);

        vm.deal(address(c), amount);

        uint256 recBalanceBefore = recipient.balance;

        vm.prank(address(this));
        try c.withdrawAll(recipient) {} catch {}

        uint256 recBalanceAfter = recipient.balance;

        assertTrue(recBalanceAfter == recBalanceBefore + amount);
    }
}
